components.css:
.ds-title-block { border: 1px solid var(--rule, #C9C4B8); border-radius: 8px; overflow: hidden; background: var(--sheet, #FFFFFF); }
.ds-tb-grid { display: grid; grid-template-columns: repeat(9, minmax(0, 1fr)); }
.ds-tb-cell { padding: .6rem .75rem .62rem; border-right: 1px solid var(--rule-soft, #E3E0D8); border-bottom: 1px solid var(--rule-soft, #E3E0D8); min-width: 0; }
.ds-tb-cell:last-child { border-right: none; }
.ds-tb-key { display: block; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .625rem; font-weight: 500; letter-spacing: .11em; text-transform: uppercase; color: var(--muted, #6B6A64); margin-bottom: .2rem; }
.ds-tb-val { display: block; font-size: 1.02rem; font-weight: 600; color: var(--ink, #16181A); font-variant-numeric: tabular-nums; letter-spacing: -.015em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-tb-val.sm { font-size: .8rem; }
.ds-tb-strip { display: flex; flex-wrap: wrap; gap: 0 1.5rem; padding: .5rem .75rem; border-top: 1px solid var(--rule-soft, #E3E0D8); background: var(--paper, #F7F6F2); }
.ds-tb-strip span { font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .625rem; letter-spacing: .1em; text-transform: uppercase; color: var(--muted, #6B6A64); }
.ds-tb-strip b { color: var(--ink, #16181A); font-weight: 600; margin-left: .34rem; font-variant-numeric: tabular-nums; }
.ds-dark .ds-title-block { background: #1B1E23; border-color: #33373E; }
.ds-dark .ds-tb-cell { border-color: #262A30; }
.ds-dark .ds-tb-key, .ds-dark .ds-tb-strip span { color: #8E8C86; }
.ds-dark .ds-tb-val, .ds-dark .ds-tb-strip b { color: #E9E7E2; }
.ds-dark .ds-tb-strip { background: #14161A; border-color: #262A30; }

.ds-btn-primary { display: inline-flex; align-items: center; gap: .45rem; border: 1px solid var(--ink, #16181A); border-radius: 6px; background: var(--ink, #16181A); color: var(--paper, #F7F6F2); font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .84rem; font-weight: 600; letter-spacing: -.005em; padding: .5rem 1rem; cursor: pointer; transition: background .12s ease, border-color .12s ease; }
.ds-btn-primary:hover { background: var(--ink2, #3C3F45); border-color: var(--ink2, #3C3F45); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--accent, #1F4FD8); outline-offset: 2px; }
.ds-btn-primary:active { background: var(--ink2, #3C3F45); }
.ds-btn-primary:disabled { opacity: .45; cursor: not-allowed; }
.ds-dark .ds-btn-primary { background: #E9E7E2; border-color: #E9E7E2; color: #14161A; }
.ds-dark .ds-btn-primary:hover { background: #C6C4BE; border-color: #C6C4BE; color: #14161A; }

.ds-btn-secondary { display: inline-flex; align-items: center; gap: .45rem; border: 1px solid var(--rule, #C9C4B8); border-radius: 6px; background: var(--sheet, #FFFFFF); color: var(--ink, #16181A); font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .84rem; font-weight: 600; letter-spacing: -.005em; padding: .5rem 1rem; cursor: pointer; transition: background .12s ease, border-color .12s ease; }
.ds-btn-secondary:hover { background: var(--paper, #F7F6F2); border-color: var(--ink2, #3C3F45); }
.ds-btn-secondary:focus-visible { outline: 2px solid var(--accent, #1F4FD8); outline-offset: 2px; }
.ds-btn-secondary:active { background: var(--paper, #F7F6F2); }
.ds-dark .ds-btn-secondary { background: #1B1E23; border-color: #33373E; color: #E9E7E2; }
.ds-dark .ds-btn-secondary:hover { background: #14161A; border-color: #C6C4BE; }

.ds-field { display: block; max-width: 18rem; font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; }
.ds-field-label { display: block; font-size: .74rem; font-weight: 500; color: var(--muted, #6B6A64); letter-spacing: .005em; margin-bottom: .18rem; }
.ds-input { width: 100%; background: var(--sheet, #FFFFFF); color: var(--ink, #16181A); border: 1px solid var(--rule, #C9C4B8); border-radius: 6px; font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .85rem; padding: .45rem .6rem; box-shadow: none; transition: border-color .12s ease, box-shadow .12s ease; }
.ds-input:hover { border-color: var(--ink2, #3C3F45); }
.ds-input:focus { border-color: var(--accent, #1F4FD8); outline: none; box-shadow: 0 0 0 2px var(--accent-soft, #E4EAFB); }
.ds-input::placeholder { color: var(--muted, #6B6A64); }
.ds-dark .ds-input { background: #1B1E23; border-color: #33373E; color: #E9E7E2; }
.ds-dark .ds-field-label { color: #8E8C86; }

.ds-tabs { display: flex; gap: .35rem; border-bottom: 1px solid var(--rule, #C9C4B8); }
.ds-tab { display: inline-flex; align-items: center; gap: .45rem; background: transparent; border: none; border-bottom: 2px solid transparent; margin-right: 1.35rem; padding: .5rem 0 .55rem; font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; font-size: .82rem; font-weight: 600; letter-spacing: -.01em; color: var(--muted, #6B6A64); cursor: pointer; transition: color .12s ease; }
.ds-tab:hover { color: var(--ink2, #3C3F45); }
.ds-tab[aria-selected='true'] { color: var(--ink, #16181A); border-bottom-color: var(--ink, #16181A); }
.ds-tab:focus-visible { outline: 2px solid var(--accent, #1F4FD8); outline-offset: 2px; }
.ds-tab .ds-ico { flex: none; }
.ds-dark .ds-tabs { border-color: #33373E; }
.ds-dark .ds-tab { color: #8E8C86; }
.ds-dark .ds-tab:hover { color: #C6C4BE; }
.ds-dark .ds-tab[aria-selected='true'] { color: #E9E7E2; border-bottom-color: #E9E7E2; }

.ds-chip { display: inline-block; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .66rem; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; padding: .28rem .5rem; border-radius: 4px; }
.ds-chip-low { background: var(--band-low-bg, #EDEBE4); color: var(--band-low-fg, #16181A); }
.ds-chip-mid { background: var(--band-mid-bg, #C2BEB3); color: var(--band-mid-fg, #16181A); }
.ds-chip-high { background: var(--band-high-bg, #16181A); color: var(--band-high-fg, #FFFFFF); }
.ds-dark .ds-chip-low { background: #232830; color: #E9E7E2; }
.ds-dark .ds-chip-mid { background: #454B54; color: #E9E7E2; }
.ds-dark .ds-chip-high { background: #E9E7E2; color: #14161A; }

.ds-verdict { border: 1px solid var(--rule, #C9C4B8); border-radius: 8px; background: var(--sheet, #FFFFFF); padding: 1rem 1.15rem 1.05rem; font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; }
.ds-verdict-head { display: flex; align-items: center; gap: .7rem; flex-wrap: wrap; margin-bottom: .45rem; }
.ds-verdict-decision { font-size: .84rem; color: var(--ink2, #3C3F45); }
.ds-verdict-decision b { color: var(--ink, #16181A); }
.ds-verdict-figure { font-size: 2.5rem; font-weight: 700; letter-spacing: -.032em; color: var(--ink, #16181A); font-variant-numeric: tabular-nums; line-height: 1.05; }
.ds-verdict-figure .ds-unit { font-size: 1.15rem; font-weight: 600; color: var(--muted, #6B6A64); margin-left: .08em; letter-spacing: -.01em; }
.ds-verdict-sub { font-size: .8rem; color: var(--muted, #6B6A64); margin-top: .18rem; }
.ds-dark .ds-verdict { background: #1B1E23; border-color: #33373E; }
.ds-dark .ds-verdict-decision { color: #C6C4BE; }
.ds-dark .ds-verdict-decision b, .ds-dark .ds-verdict-figure { color: #E9E7E2; }
.ds-dark .ds-verdict-sub, .ds-dark .ds-verdict-figure .ds-unit { color: #8E8C86; }

.ds-scale { border: 1px solid var(--rule, #C9C4B8); border-radius: 8px; background: var(--sheet, #FFFFFF); padding: .85rem 1rem .7rem; font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; }
.ds-scale-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 1.7rem; gap: 1rem; }
.ds-scale-title { font-size: .78rem; font-weight: 600; color: var(--ink, #16181A); }
.ds-scale-note { font-size: .72rem; color: var(--muted, #6B6A64); }
.ds-scale-track { position: relative; height: 26px; border: 1px solid var(--rule, #C9C4B8); border-radius: 4px; display: flex; overflow: visible; }
.ds-scale-seg { height: 100%; display: flex; align-items: center; justify-content: flex-start; padding-left: .55rem; }
.ds-scale-seg span { font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .58rem; letter-spacing: .11em; text-transform: uppercase; }
.ds-seg-low { background: var(--band-low-bg, #EDEBE4); color: var(--band-low-fg, #16181A); flex: none; }
.ds-seg-mid { background: var(--band-mid-bg, #C2BEB3); color: var(--band-mid-fg, #16181A); flex: none; }
.ds-seg-high { background: var(--band-high-bg, #16181A); color: var(--band-high-fg, #FFFFFF); flex: 1; }
.ds-scale-marker { position: absolute; top: -6px; bottom: -6px; width: 2px; background: var(--ink, #16181A); transform: translateX(-1px); }
.ds-scale-marker::after { content: ''; position: absolute; top: -4px; left: -3px; width: 8px; height: 8px; background: var(--ink, #16181A); border-radius: 50%; }
.ds-scale-marker-val { position: absolute; top: -1.5rem; left: 50%; transform: translateX(-50%); font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .68rem; font-weight: 600; color: var(--ink, #16181A); white-space: nowrap; background: var(--sheet, #FFFFFF); border: 1px solid var(--rule, #C9C4B8); border-radius: 3px; padding: .1rem .32rem; }
.ds-scale-ticks { position: relative; height: 1rem; margin-top: .3rem; }
.ds-scale-tick { position: absolute; transform: translateX(-50%); font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .58rem; letter-spacing: .08em; color: var(--muted, #6B6A64); white-space: nowrap; }
.ds-scale-tick.hard { color: var(--ink2, #3C3F45); font-weight: 600; }
.ds-scale-tick:first-child { transform: translateX(-8%); }
.ds-scale-tick:last-child { transform: translateX(-92%); }
.ds-dark .ds-scale { background: #1B1E23; border-color: #33373E; }
.ds-dark .ds-scale-title, .ds-dark .ds-scale-marker-val { color: #E9E7E2; }
.ds-dark .ds-scale-note, .ds-dark .ds-scale-tick { color: #8E8C86; }
.ds-dark .ds-scale-tick.hard { color: #C6C4BE; }
.ds-dark .ds-scale-marker, .ds-dark .ds-scale-marker::after { background: #E9E7E2; }
.ds-dark .ds-scale-marker-val { background: #1B1E23; border-color: #33373E; }
.ds-dark .ds-seg-low { background: #232830; color: #E9E7E2; }
.ds-dark .ds-seg-mid { background: #454B54; color: #E9E7E2; }
.ds-dark .ds-seg-high { background: #E9E7E2; color: #14161A; }

.ds-cm { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--rule, #C9C4B8); border-radius: 8px; overflow: hidden; background: var(--sheet, #FFFFFF); font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; }
.ds-cm-cell { padding: .6rem .85rem .7rem; border-right: 1px solid var(--rule-soft, #E3E0D8); border-bottom: 1px solid var(--rule-soft, #E3E0D8); }
.ds-cm-cell:nth-child(2n) { border-right: none; }
.ds-cm-cell:nth-child(n+3) { border-bottom: none; }
.ds-cm-key { display: block; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .6rem; letter-spacing: .12em; text-transform: uppercase; color: var(--muted, #6B6A64); margin-bottom: .22rem; }
.ds-cm-val { display: block; font-size: 1.55rem; font-weight: 650; letter-spacing: -.025em; color: var(--ink, #16181A); font-variant-numeric: tabular-nums; line-height: 1.15; }
.ds-cm-desc { display: block; font-size: .76rem; color: var(--muted, #6B6A64); margin-top: .12rem; }
.ds-cm-cell.hit { background: var(--ramp1, #EDEBE4); }
.ds-dark .ds-cm { background: #1B1E23; border-color: #33373E; }
.ds-dark .ds-cm-cell { border-color: #262A30; }
.ds-dark .ds-cm-key, .ds-dark .ds-cm-desc { color: #8E8C86; }
.ds-dark .ds-cm-val { color: #E9E7E2; }
.ds-dark .ds-cm-cell.hit { background: #232830; }

.ds-summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border: 1px solid var(--rule, #C9C4B8); border-radius: 8px; overflow: hidden; background: var(--sheet, #FFFFFF); font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; }
.ds-summary > div { padding: .62rem .8rem; border-right: 1px solid var(--rule-soft, #E3E0D8); }
.ds-summary > div:last-child { border-right: none; }
.ds-summary-key { display: block; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: .625rem; font-weight: 500; letter-spacing: .11em; text-transform: uppercase; color: var(--muted, #6B6A64); margin-bottom: .2rem; }
.ds-summary-val { display: block; font-size: 1.02rem; font-weight: 600; color: var(--ink, #16181A); font-variant-numeric: tabular-nums; letter-spacing: -.015em; }
.ds-dark .ds-summary { background: #1B1E23; border-color: #33373E; }
.ds-dark .ds-summary > div { border-color: #262A30; }
.ds-dark .ds-summary-key { color: #8E8C86; }
.ds-dark .ds-summary-val { color: #E9E7E2; }

.ds-plate { margin: 0; font-family: 'Archivo', 'Segoe UI', system-ui, sans-serif; }
.ds-plate-frame { display: block; border: 1px solid var(--rule, #C9C4B8); border-radius: 8px; background: #FFFFFF; aspect-ratio: 12 / 3.7; }
.ds-plate-cap { font-size: .78rem; color: var(--muted, #6B6A64); padding: .5rem .05rem .55rem; line-height: 1.5; }
.ds-dark .ds-plate-frame { border-color: #33373E; }
.ds-dark .ds-plate-cap { color: #8E8C86; }
